<?php
use Illuminate\Support\Facades\Route;
use App\Http\Controllers\Staff\{AuthController, DashboardController, ContactController, ProductController, QuoteController, AppointmentController, InterventionController, UserController, InvoiceController, MessageController};
Route::prefix('admin')->group(function () {
    Route::get('connexion', [AuthController::class, 'form'])->name('login');
    Route::post('connexion', [AuthController::class, 'login'])->middleware('throttle:20,1')->name('staff.login');
    Route::middleware(['auth', 'auth.session', 'staff'])->name('staff.')->group(function () {
        Route::get('/', DashboardController::class)->name('dashboard');
        Route::post('deconnexion', [AuthController::class, 'logout'])->name('logout');
        Route::get('notifications', [App\Http\Controllers\Staff\PushController::class, 'index'])->name('notifications.index');
        Route::get('notifications/recentes', [App\Http\Controllers\Staff\PushController::class, 'recent'])->middleware('throttle:60,1')->name('notifications.recent');
        Route::get('push/cle-publique', [App\Http\Controllers\Staff\PushController::class, 'publicKey'])->name('push.public-key');
        Route::post('push/abonnement', [App\Http\Controllers\Staff\PushController::class, 'subscribe'])->middleware('throttle:20,1')->name('push.subscribe');
        Route::delete('push/abonnement', [App\Http\Controllers\Staff\PushController::class, 'unsubscribe'])->middleware('throttle:20,1')->name('push.unsubscribe');
        Route::post('notifications/{notification}/lu', [App\Http\Controllers\Staff\PushController::class, 'markRead'])->name('notifications.read');
        Route::get('mot-de-passe', [AuthController::class, 'password'])->name('password');
        Route::post('mot-de-passe', [AuthController::class, 'changePassword'])->middleware('throttle:5,1')->name('password.update');
        Route::get('recherche', App\Http\Controllers\Staff\SearchController::class)->name('search');
        Route::get('profil', [App\Http\Controllers\Staff\ProfileController::class, 'profile'])->name('profile');
        Route::patch('profil', [App\Http\Controllers\Staff\ProfileController::class, 'updateProfile'])->name('profile.update');
        Route::get('profil/couverture', [App\Http\Controllers\Staff\ProfileController::class, 'cover'])->name('profile.cover');
        Route::get('parametres', [App\Http\Controllers\Staff\ProfileController::class, 'settings'])->name('settings');
        Route::patch('parametres', [App\Http\Controllers\Staff\ProfileController::class, 'updateSettings'])->name('settings.update');
        Route::post('parametres/autres-appareils', [App\Http\Controllers\Staff\ProfileController::class, 'logoutOthers'])->middleware('throttle:5,1')->name('settings.logout-others');
        Route::get('devis', [QuoteController::class, 'index'])->name('quotes.index');
        Route::get('illustrations-produits/{product}',[App\Http\Controllers\MediaController::class,'staffProduct'])->name('quote-product-image');
        Route::get('devis/nouveau', [App\Http\Controllers\Staff\QuoteFormController::class, 'create'])->name('quotes.create');
        Route::post('devis', [App\Http\Controllers\Staff\QuoteFormController::class, 'store'])->name('quotes.store');
        Route::post('devis/chiffrer', [App\Http\Controllers\Staff\QuoteFormController::class, 'calculate'])->middleware('throttle:60,1')->name('quotes.calculate');
        Route::get('devis/{quote}/formulaire', [App\Http\Controllers\Staff\QuoteFormController::class, 'edit'])->name('quotes.edit');
        Route::put('devis/{quote}/formulaire', [App\Http\Controllers\Staff\QuoteFormController::class, 'update'])->name('quotes.form.update');
        Route::post('devis/{quote}/paiements', [App\Http\Controllers\Staff\QuoteFormController::class, 'receipt'])->name('quotes.receipt');
        Route::get('devis/{quote}', [QuoteController::class, 'show'])->name('quotes.show');
        Route::put('devis/{quote}', [QuoteController::class, 'update'])->name('quotes.update');
        Route::get('devis/{quote}/pdf', [QuoteController::class, 'pdf'])->name('quotes.pdf');
        Route::get('devis/{quote}/photos/{media}', [QuoteController::class, 'photo'])->whereNumber('media')->name('quotes.photo');
        Route::get('rendez-vous', [AppointmentController::class, 'index'])->name('appointments.index');
        Route::get('rendez-vous/{appointment}', [AppointmentController::class, 'show'])->name('appointments.show');
