                Route::get('mise-en-page/{type?}', [App\Http\Controllers\Staff\DocumentLayoutController::class,'edit'])->name('layouts.edit');
                Route::post('mise-en-page/{type}', [App\Http\Controllers\Staff\DocumentLayoutController::class,'save'])->name('layouts.save');
                Route::post('mise-en-page/{type}/apercu', [App\Http\Controllers\Staff\DocumentLayoutController::class,'preview'])->middleware('throttle:60,1')->name('layouts.preview');
                Route::post('mise-en-page/{type}/versions/{revision}', [App\Http\Controllers\Staff\DocumentLayoutController::class,'restore'])->name('layouts.restore');
                Route::get('communications', [App\Http\Controllers\Staff\CommunicationController::class,'index'])->name('communications.index');
                Route::get('communications/modeles/{template}', [App\Http\Controllers\Staff\CommunicationController::class,'edit'])->name('communications.edit');
                Route::post('communications/modeles/{template}', [App\Http\Controllers\Staff\CommunicationController::class,'update'])->name('communications.update');
                Route::post('communications/modeles/{template}/apercu', [App\Http\Controllers\Staff\CommunicationController::class,'preview'])->name('communications.preview');
                Route::put('communications/regles/{rule}', [App\Http\Controllers\Staff\CommunicationController::class,'rule'])->name('communications.rule');
                Route::post('communications/connexion', [App\Http\Controllers\Staff\CommunicationController::class,'connection'])->middleware('throttle:3,1')->name('communications.connection');
                Route::post('communications/executer', [App\Http\Controllers\Staff\CommunicationController::class,'process'])->middleware('throttle:3,1')->name('communications.process');
                Route::resource('contents', App\Http\Controllers\Staff\SiteContentController::class)->except(['show', 'destroy']);
                Route::get('equipe', [UserController::class, 'index'])->name('users.index');
                Route::post('equipe', [UserController::class, 'store'])->name('users.store');
                Route::put('equipe/{user}', [UserController::class, 'update'])->name('users.update');
            });
            Route::get('documents/{issue}/archive', [App\Http\Controllers\Staff\DocumentLayoutController::class,'archive'])->name('layouts.archive');
            Route::post('devis/{quote}/presentation', [App\Http\Controllers\Staff\DocumentLayoutController::class,'metadata'])->name('layouts.metadata');
            Route::get('devis/{quote}/paiements/{payment}/recu', [App\Http\Controllers\Staff\DocumentLayoutController::class,'receipt'])->name('layouts.receipt');
            Route::post('devis/{quote}/avancement', [App\Http\Controllers\Staff\QuoteWorkflowController::class,'update'])->name('quotes.workflow');
            Route::patch('catalogue/visibilite', [ProductController::class, 'catalogueVisibility'])->name('catalogue.visibility');
            Route::post('devis/{quote}/paiements/{payment}/annuler', [App\Http\Controllers\Staff\QuoteFormController::class, 'voidReceipt'])->name('quotes.receipt.void');
            Route::get('options-devis', [App\Http\Controllers\Staff\QuoteOptionController::class, 'index'])->name('quote-options.index');
            Route::post('options-devis', [App\Http\Controllers\Staff\QuoteOptionController::class, 'store'])->name('quote-options.store');
            Route::put('options-devis/{option}', [App\Http\Controllers\Staff\QuoteOptionController::class, 'update'])->name('quote-options.update');
            Route::get('media/{media}', [App\Http\Controllers\MediaController::class, 'preview'])->whereNumber('media')->name('media.preview');
            Route::resource('contacts', ContactController::class)->only(['index', 'store', 'show', 'update']);
            Route::resource('products', ProductController::class)->except(['show', 'destroy']);
            Route::patch('products/{product}/visibility', [ProductController::class, 'visibility'])->name('products.visibility');
            Route::put('rendez-vous/{appointment}', [AppointmentController::class, 'update'])->name('appointments.update');
            Route::post('prestations', [InterventionController::class, 'store'])->name('interventions.store');
            Route::get('factures', [InvoiceController::class, 'index'])->name('invoices.index');
            Route::post('devis/{quote}/facture', [InvoiceController::class, 'create'])->name('invoices.create');
            Route::get('factures/{invoice}', [InvoiceController::class, 'show'])->name('invoices.show');
            Route::post('factures/{invoice}/emettre', [InvoiceController::class, 'issue'])->name('invoices.issue');
            Route::post('factures/{invoice}/paiement', [InvoiceController::class, 'paid'])->name('invoices.paid');
            Route::get('factures/{invoice}/pdf', [InvoiceController::class, 'pdf'])->name('invoices.pdf');
            // Archives et corbeille : {type} = devis, catalogue, clients, rendez-vous, messages, factures.
            Route::get('corbeille', [App\Http\Controllers\Staff\TrashController::class, 'index'])->name('trash.index');
            Route::post('elements/{type}/{id}/archiver', [App\Http\Controllers\Staff\TrashController::class, 'archive'])->whereNumber('id')->name('trash.archive');
            Route::post('elements/{type}/{id}/desarchiver', [App\Http\Controllers\Staff\TrashController::class, 'unarchive'])->whereNumber('id')->name('trash.unarchive');
            Route::delete('elements/{type}/{id}', [App\Http\Controllers\Staff\TrashController::class, 'destroy'])->whereNumber('id')->name('trash.destroy');
            Route::post('corbeille/{type}/{id}/restaurer', [App\Http\Controllers\Staff\TrashController::class, 'restore'])->whereNumber('id')->name('trash.restore');
            Route::delete('corbeille/{type}/{id}', [App\Http\Controllers\Staff\TrashController::class, 'forceDestroy'])->whereNumber('id')->name('trash.force');
            Route::get('messages', [MessageController::class, 'index'])->name('messages.index');
            Route::get('messages/nouveau', [MessageController::class, 'create'])->name('messages.create');
            Route::post('messages', [MessageController::class, 'store'])->name('messages.store');
            Route::post('messages/synchroniser', [MessageController::class, 'sync'])->middleware('throttle:3,1')->name('messages.sync');
            Route::get('messages/{message}', [MessageController::class, 'show'])->name('messages.show');
            Route::put('messages/{message}', [MessageController::class, 'update'])->name('messages.update');
            Route::get('messages/{message}/document', [MessageController::class, 'attachment'])->name('messages.attachment');
            Route::post('messages/{message}/envoyer', [MessageController::class, 'send'])->middleware('throttle:10,1')->name('messages.send');
            Route::get('messages/{message}/whatsapp', [MessageController::class,'whatsapp'])->name('messages.whatsapp');
            Route::post('messages/{message}/partage', [MessageController::class,'shared'])->name('messages.shared');
            Route::post('messages/{message}/annuler', [MessageController::class,'cancel'])->name('messages.cancel');
        });
    });
});
